#set ($bxNames = ['sideToolbar', 'alertBlocks', 'macroShortcuts', 'tablePasteClean', 'editorFullscreen', 'editorOutline', 'tableRows', 'tableColumns', 'tableDelete', 'tableDuplicate', 'tableMove', 'tableCellColors', 'tableBandColors', 'tableMerge', 'tableShortcuts', 'stickyHeaders', 'copyTableTsv', 'pageSearch', 'restoreReadPosition'])
#set ($bxObj = false)
#if ($xcontext.userReference)
  #set ($bxSettingsRef = $services.model.createDocumentReference($xcontext.database, ['BetterxWiki', 'UserSettings'], $xcontext.userReference.name))
  #set ($bxSettingsDoc = $xwiki.getDocument($bxSettingsRef))
  #set ($bxObj = $bxSettingsDoc.getObject('BetterxWiki.UserSettingsClass'))
#end
#set ($bxSettings = {})
#foreach ($bxName in $bxNames)
  #if ($bxObj && "$!bxObj.getValue($bxName)" == '0')
    #set ($discard = $bxSettings.put($bxName, false))
  #else
    #set ($discard = $bxSettings.put($bxName, true))
  #end
#end
window.BETTERXWIKI_SETTINGS = $jsontool.serialize($bxSettings);
(function () {
  if (document.querySelector("script[data-betterxwiki-client]")) return;
  var node = document.createElement("script");
  node.async = false;
  node.setAttribute("data-betterxwiki-client", "1");
  var url = "$xwiki.getAttachmentURL('BetterxWiki.Client', 'betterxwiki.js')";
  node.src = url + (url.indexOf("?") >= 0 ? "&" : "?") + "v=1.0.2";
  document.documentElement.appendChild(node);
})();

#betterxwiki-toolbar,
#betterxwiki-editorbar,
#betterxwiki-find {
  position: fixed;
  z-index: 100001;
  display: flex;
  align-items: center;
  gap: 2px;
  margin: 0;
  padding: 4px;
  background: #fff;
  border: 1px solid #d8dee6;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(20, 30, 50, 0.14);
  color: #243044;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  user-select: none;
}

#betterxwiki-toolbar {
  flex-wrap: wrap;
  justify-content: center;
  max-width: min(440px, calc(100vw - 16px));
}

.cke_toolbox .bx-cke-tools {
  float: none;
  display: inline-flex;
  align-items: center;
  vertical-align: top;
}

.cke_toolbox #betterxwiki-toolbar,
.cke_toolbox #betterxwiki-editorbar {
  position: static !important;
  top: auto !important;
  left: auto !important;
  display: inline-flex !important;
  flex-direction: row;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0;
  max-width: none;
  margin: 0 6px 5px 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

.cke_toolbox #betterxwiki-toolbar[hidden],
.cke_toolbox #betterxwiki-editorbar[hidden] {
  display: none !important;
}

.cke_toolbox .bx-cke-tools:not(:has(#betterxwiki-editorbar:not([hidden]))):not(:has(#betterxwiki-toolbar:not([hidden]))) {
  display: none !important;
}

.cke_toolbox .bx-group {
  flex-direction: row;
  margin: 0 6px 0 0;
  padding: 2px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.06);
}

.cke_toolbox .bx-group.is-separated {
  margin-left: 0;
  padding-left: 2px;
  border-left: 0;
  margin-top: 0;
  padding-top: 2px;
  border-top: 0;
}

.cke_toolbox #betterxwiki-toolbar button,
.cke_toolbox #betterxwiki-editorbar button {
  width: 28px !important;
  height: 28px !important;
  display: inline-flex !important;
  float: none !important;
}

#betterxwiki-toolbar[hidden],
#betterxwiki-editorbar[hidden],
#betterxwiki-find[hidden],
#betterxwiki-outline[hidden],
#betterxwiki-copy[hidden],
#betterxwiki-search[hidden] {
  display: none !important;
}

#betterxwiki-toolbar .bx-group,
#betterxwiki-editorbar .bx-group {
  display: flex;
  align-items: center;
  gap: 2px;
}

#betterxwiki-toolbar .bx-group[hidden],
#betterxwiki-editorbar .bx-group[hidden] {
  display: none !important;
}

#betterxwiki-toolbar button,
#betterxwiki-editorbar button,
#betterxwiki-find button,
#betterxwiki-outline button,
#betterxwiki-copy,
#betterxwiki-search {
  all: unset;
  box-sizing: border-box;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: #243044;
  cursor: pointer;
}

#betterxwiki-toolbar button:hover:not(:disabled),
#betterxwiki-editorbar button:hover:not(:disabled),
#betterxwiki-find button:hover,
#betterxwiki-outline button:hover,
#betterxwiki-copy:hover,
#betterxwiki-search:hover {
  background: #f0f3f7;
}

#betterxwiki-toolbar button:disabled {
  opacity: 0.35;
  cursor: default;
}

#betterxwiki-toolbar button.is-active,
#betterxwiki-editorbar button.is-active {
  background: #e7eefb;
}

#betterxwiki-toolbar button svg,
#betterxwiki-editorbar button svg,
#betterxwiki-find button svg,
#betterxwiki-search svg {
  width: 18px;
  height: 18px;
  display: block;
  pointer-events: none;
}

#betterxwiki-toolbar .bx-swatch,
#betterxwiki-editorbar .bx-swatch {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.18);
  pointer-events: none;
}

#betterxwiki-toolbar button.is-active .bx-swatch {
  box-shadow: 0 0 0 2px #fff, 0 0 0 4px #2f6fde;
}

#betterxwiki-outline {
  position: fixed;
  z-index: 100001;
  width: 220px;
  max-height: min(60vh, 480px);
  overflow: auto;
  padding: 8px;
  background: #fff;
  border: 1px solid #d8dee6;
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(20, 30, 50, 0.14);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

#betterxwiki-outline p {
  margin: 4px;
  color: #6b7787;
  font-size: 12px;
}

#betterxwiki-outline button {
  width: 100%;
  height: auto;
  min-height: 26px;
  justify-content: flex-start;
  padding: 4px 6px;
  font-size: 12px;
  line-height: 1.3;
  text-align: left;
}

#betterxwiki-find {
  top: 12px;
  right: 12px;
  gap: 4px;
  z-index: 100002;
}

#betterxwiki-find input {
  all: unset;
  box-sizing: border-box;
  width: 180px;
  height: 28px;
  padding: 0 8px;
  border-radius: 6px;
  background: #f4f6f8;
  font-size: 13px;
}

#betterxwiki-find .bx-find-count {
  min-width: 3.2em;
  color: #6b7787;
  font-size: 12px;
  text-align: center;
}

#betterxwiki-copy {
  position: fixed;
  z-index: 100000;
  width: auto;
  height: 26px;
  padding: 0 8px;
  background: #fff;
  border: 1px solid #d8dee6;
  border-radius: 6px;
  box-shadow: 0 2px 8px rgba(20, 30, 50, 0.12);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
}

#betterxwiki-search {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 100000;
  width: 36px;
  height: 36px;
  background: #fff;
  border: 1px solid #d8dee6;
  border-radius: 999px;
  box-shadow: 0 4px 16px rgba(20, 30, 50, 0.14);
}

html.bx-sticky #xwikicontent thead th,
html.bx-sticky #xwikicontent table > tr:first-child > th,
html.bx-sticky #xwikicontent table > thead > tr > th,
html.bx-sticky #xwikicontent table > tbody > tr:first-child > th {
  position: sticky !important;
  top: var(--bx-sticky-top, 0px);
  z-index: 4;
  background: var(--table-head-bg, #fff);
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.12);
}

html.bx-sticky #contentcolumn,
html.bx-sticky #contentcolumn .main,
html.bx-sticky #mainContentArea,
html.bx-sticky #xwikicontent,
html.bx-sticky #xwikicontent table {
  overflow: visible !important;
}

html.bx-sticky #xwikicontent table {
  border-collapse: separate !important;
  border-spacing: 0;
}

.cke.bx-fullscreen {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: var(--bx-outline-reserve, 0px) !important;
  bottom: var(--bx-fullscreen-bottom, 0px) !important;
  width: auto !important;
  height: auto !important;
  z-index: 100000 !important;
  background: #fff;
}

html.bx-side-toolbar:has(#xwikicontent.cke_editable) #mainContentArea,
html.bx-side-toolbar:has(#xwikicontent.cke_editable) #contentcolumn .main > #hierarchy_breadcrumb {
  margin-right: 82px !important;
}

html.bx-side-toolbar .cke_float {
  position: fixed !important;
  top: 72px !important;
  right: 12px !important;
  left: auto !important;
  bottom: auto !important;
  width: 58px !important;
  max-height: calc(100vh - 88px) !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: auto !important;
  z-index: 9999 !important;
  border: 1px solid #d0d5dd !important;
  border-radius: 18px !important;
  background: #fff !important;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.16) !important;
  scrollbar-width: thin;
  scrollbar-color: #d0d5dd transparent;
}

html.bx-side-toolbar .cke_float .cke_inner,
html.bx-side-toolbar .cke_float .cke_top,
html.bx-side-toolbar .cke_float .cke_toolbox {
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

html.bx-side-toolbar .cke_float .cke_top {
  position: static !important;
  top: auto !important;
  right: auto !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 8px !important;
  overflow: visible !important;
  border-radius: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_toolbox {
  display: flex !important;
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
  width: auto !important;
}

html.bx-side-toolbar .cke_float .cke_toolbar,
html.bx-side-toolbar .cke_float .bx-cke-tools {
  float: none !important;
  display: block !important;
  width: 100% !important;
  margin: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_toolbar_start,
html.bx-side-toolbar .cke_float .cke_toolbar_end,
html.bx-side-toolbar .cke_float .cke_toolbar_break,
html.bx-side-toolbar .cke_float .cke_toolbar_separator {
  display: none !important;
}

html.bx-side-toolbar .cke_float .cke_toolgroup,
html.bx-side-toolbar .cke_float .bx-group {
  float: none !important;
  display: grid !important;
  grid-template-columns: 1fr;
  gap: 2px;
  width: auto !important;
  margin: 0 !important;
  padding: 3px !important;
  border: 0 !important;
  border-radius: 12px !important;
  background: #f4f6f8 !important;
  background-image: none !important;
  box-shadow: none !important;
}

html.bx-side-toolbar .cke_float a.cke_button,
html.bx-side-toolbar .cke_float a.cke_button_off,
html.bx-side-toolbar .cke_float a.cke_button_disabled,
html.bx-side-toolbar .cke_float #betterxwiki-editorbar button {
  float: none !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 2px;
  width: 100% !important;
  height: 34px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 9px !important;
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
}

html.bx-side-toolbar .cke_float .cke_button_arrow {
  position: static !important;
  display: inline-block !important;
  flex: none;
  width: 0 !important;
  height: 0 !important;
  margin: 5px 0 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-left: 3px solid transparent !important;
  border-right: 3px solid transparent !important;
  border-top: 4px solid #6b7787 !important;
  background: none !important;
  cursor: pointer;
}

html.bx-side-toolbar .cke_float .cke_button_icon {
  float: none !important;
  display: block !important;
  width: 16px !important;
  height: 16px !important;
  margin: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_button_label,
html.bx-side-toolbar .cke_float .cke_button_label.cke_button__basicstyles_label {
  display: none !important;
}

html.bx-side-toolbar .cke_float a.cke_button:hover,
html.bx-side-toolbar .cke_float a.cke_button:focus,
html.bx-side-toolbar .cke_float #betterxwiki-editorbar button:hover {
  background: #eef2f6 !important;
}

html.bx-side-toolbar .cke_float a.cke_button_on {
  background: #007aff !important;
}

html.bx-side-toolbar .cke_float a.cke_button_on .cke_button_arrow {
  border-top-color: #fff !important;
}

html.bx-side-toolbar .cke_float .cke_combo {
  float: none !important;
  display: block !important;
  width: auto !important;
  margin: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_combo_button {
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 2px;
  width: 100% !important;
  height: 34px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 12px !important;
  background: #f4f6f8 !important;
  background-image: none !important;
  box-shadow: none !important;
}

html.bx-side-toolbar .cke_float .cke_combo_text {
  display: block !important;
  float: none !important;
  flex: none;
  width: auto !important;
  max-width: none;
  overflow: hidden;
  padding: 0 !important;
  color: #243044 !important;
  font-size: 13px !important;
  font-weight: 700;
  line-height: 34px !important;
  text-align: center;
  text-shadow: none !important;
}

html.bx-side-toolbar .cke_float .cke_combo__format .cke_combo_text,
html.bx-side-toolbar .cke_float .cke_combo__styles .cke_combo_text {
  font-size: 0 !important;
  line-height: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_combo__format .cke_combo_text::before,
html.bx-side-toolbar .cke_float .cke_combo__styles .cke_combo_text::before {
  font-size: 13px;
  font-weight: 700;
  line-height: 34px;
}

html.bx-side-toolbar .cke_float .cke_combo__format .cke_combo_text::before {
  content: "F";
}

html.bx-side-toolbar .cke_float .cke_combo__styles .cke_combo_text::before {
  content: "S";
}

html.bx-side-toolbar .cke_float .cke_combo_open {
  float: none !important;
  position: static !important;
  display: flex !important;
  flex: none;
  align-items: center;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
}

html.bx-side-toolbar .cke_float .cke_combo_arrow {
  float: none !important;
  margin: 4px 0 0 !important;
  border-top-color: #6b7787 !important;
}

html.bx-side-toolbar .cke_float #betterxwiki-editorbar {
  position: static !important;
  display: flex !important;
  flex-direction: column;
  align-items: stretch;
  width: auto !important;
  max-width: none !important;
  margin: 0 0 6px !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

html.bx-side-toolbar .cke_float #betterxwiki-editorbar[hidden] {
  display: none !important;
}

html.bx-side-toolbar .cke_panel.bx-float-panel {
  z-index: 100010 !important;
  max-height: calc(100vh - 24px) !important;
  overflow: auto !important;
}
